from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
left_wheel = Motor(Port.F, Direction.COUNTERCLOCKWISE)
right_wheel = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(left_wheel, right_wheel, 62.4, 128)

async def main():
    drive_base.use_gyro(True)
    # diameter 62.4
    # wheel base 128
    left_wheel.reset_angle(0)
    right_wheel.reset_angle(0)
    await wait(1000)
    await drive_base.turn(360)
    await wait(1000)
    # Curve
    # + + / clockwise forward
    # + - \ counterclockwise reverse
    # - - / clockwise reverse
    # - + \ counterclockwise forward
    print('Left Wheel position', left_wheel.angle())
    print('Right Wheel position', right_wheel.angle())
    print('abc')
    await multitask(
        wait(0),
    )


run_task(main())